const b = $json.body || $json;
const nicho = String(b.nicho || b.tema || '').trim();
const libro = String(b.libro || b.titulo || '').trim();
if (!nicho && !libro) return [{ json: { ok: false, error: 'falta nicho o libro' } }];
const slug = (libro || nicho).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
return [{ json: {
  ok: true, sistema: '11-kdp-resumenes', etapa: 'nicho', sin_api: true,
  jobId: `KDP-${Date.now()}`, slug, nicho, libro,
  brief: { accion: 'resumir_y_listing', slug, nicho, libro },
  todo: 'SIN API. Después: analisis-de-proyectos + kdp_main.py',
  at: new Date().toISOString()
}}];
